{
  "description": "The creature is shown in right-facing profile standing on a plain light background with a faint shadow beneath its feet. It has a stout, quadrupedal body completely covered in long, shaggy brown fur that is darker on the legs and back and lighter cream-tan on the chest, sides, and muzzle. The head is broad with a bear-like muzzle, black nose, and small dark eyes. A single long, smooth, dark brown to black curved horn rises from the center of the forehead and arches backward and upward. The back from the shoulders to the rump is covered by a large, glossy, domed, dark reddish-brown shell with fine horizontal ridges and reflective highlights, divided into a smaller anterior section and a larger posterior section.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, bear-like with a blunt muzzle, black nose at the tip, small brown eyes, light tan fur around the muzzle and lower face grading to darker brown on the forehead and cheeks, mouth closed with a slight smile line",
      "where": "at the front end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "single, long, smooth, glossy dark brown to black, thick at the base and tapering to a sharp point, strongly curved backward then upward in a sickle shape",
      "where": "arising from the midline of the forehead just above and between the eyes"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred, medium brown with darker interiors, upright",
      "where": "on top of the head behind the horn, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar limbs covered in long shaggy dark brown fur, with lighter fur on the inner chest and flank areas",
      "where": "two forelegs under the chest/shoulder region and two hindlegs under the rear/hip region, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large paws with visible pale, curved claws (three to five per paw in view), dark fur covering the top and sides, broad soles",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very small, short, stubby and furry, dark brown, barely protruding",
      "where": "at the extreme rear of the body just above and behind the left hind leg"
    },
    {
      "part": "shell",
      "looks_like": "large, highly glossy, domed, dark reddish-brown with fine parallel horizontal ridges and bright specular highlights, divided by a narrow transverse gap into a smaller anterior dome over the shoulders and a larger posterior dome over the back and hips",
      "where": "covering the entire dorsal surface from just behind the neck to just before the tail"
    },
    {
      "part": "plates",
      "looks_like": "a continuous rim of small, rectangular to oval, brown, slightly raised segments each with a central oval depression, forming a segmented border",
      "where": "encircling the lower edge of both shell sections where the shell meets the fur"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy fur with color gradation: dark chocolate brown on the outer legs and back edges, medium brown on the head and upper body, and creamy off-white on the chest, lower sides and underparts; no distinct spots or stripes",
      "where": "over the entire body except the shell and horn"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
